def _forma(titolo: str, i: int) -> str:
    if i % 4 == 0:
        return titolo.upper()
    if i % 4 == 2:
        return titolo[:1].upper() + titolo[1:].lower()
    return titolo


def _testo(rule_id: str, i: int) -> str:
    autorita, _label, _sezione, titoli, corpi = _REGOLE[rule_id]
    citta = _CITTA[i % len(_CITTA)]
    intestazioni = _INTESTAZIONI[autorita]
    intestazione = intestazioni[i % len(intestazioni)].format(c=citta, C=citta.upper())
    nome, altro = _NOMI[i % len(_NOMI)], _NOMI[(i + 3) % len(_NOMI)]
    numero = 100 + 37 * i + len(rule_id)
    righe = [intestazione] if i % 5 != 4 else []
    if i % 3 == 1:
        righe.append(f"Proc. pen. n. {numero}/2026 R.G.N.R.")
    righe.append(_forma(titoli[i % len(titoli)], i))
    righe.append(corpi[i % len(corpi)].format(n=nome, m=altro, c=citta, k=numero))
    if i % 2:
        righe.append(corpi[(i + 1) % len(corpi)].format(n=nome, m=altro, c=citta, k=numero))
    righe.extend(_RIEMPITIVI[(i + j) % len(_RIEMPITIVI)] for j in range(i % 4))
    righe.append(f"{citta}, {1 + i:02d}/0{1 + i % 9}/2026")
    return "\n".join(righe)


# regola -> (testo, etichetta attesa, sezione attesa)
CAMPIONI: dict[str, tuple[str, str, str]] = {
    rule_id: (_testo(rule_id, 1), voce[1], voce[2]) for rule_id, voce in _REGOLE.items()
}

# regola -> dieci documenti diversi, tutti con l'etichetta e la sezione del campione
VARIANTI: dict[str, tuple[str, ...]] = {
    rule_id: tuple(_testo(rule_id, 10 + i) for i in range(10)) for rule_id in _REGOLE
}
